INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_rscam_1', 'oa_rscam_customs', 'What to Know About Shipping and Declaring Lithium Batteries by Individuals', 'Air transport of items containing lithium batteries is subject to rated-energy (Wh) limits; items exceeding the specifications cannot be transported by air. Declarations must truthfully state the item name and value.', 'https://customs.example/li-battery-notice', '2026-06-08');
INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_rscam_2', 'oa_rscam_brand', 'Official Warranty/Qualification and Overseas After-Sales Information', 'Before a listing is sold, verify the condition, authenticity, and listing verification code using the item/SKU details; fully document buyer price negotiations and platform fees and manage their deadlines.', 'https://brand.example/notice', '2026-06-08');
INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_rscam_3', 'oa_rscam_card', 'Card-Security Tips for Overseas and Foreign-Currency Transactions', 'Foreign-currency transactions may post with exchange-rate and timing differences; if you find duplicate charges or an unfamiliar merchant, verify them promptly and you may initiate a dispute.', 'https://card.example/fx-safety', '2026-06-08');
INSERT INTO official_account_posts (post_id, account_id, title, summary, url, published_at) VALUES ('post_rscam_4', 'oa_rscam_brand', 'Comparison of Three Handling Options', 'Hold to the listed price and use platform escrow (¥780 concession, fastest); offer a small discount for a quick sale (¥450 concession, middle ground); relist at a higher price and wait for a buyer (no concession, but requires waiting and inspection costs approximately ¥600). Weigh the options based on the actual net amount received and the likelihood of success.', 'https://brand.example/options', '2026-06-08');
